// Host tests for the EARP1 sample pack and the LGPL-free sample player.
//
// Usage: ear_sample_player_test <earby-string-pack.bin>
//
// The real pack (generated by synthNotes/tools/build_sample_pack.py) is loaded and rendered, and
// corrupted copies exercise every rejection path. A second, synthetic pack with a constant PCM
// plateau makes the release envelope, velocity mapping, polyphony and mono/stereo checks exact
// instead of waveform dependent.
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <string>
#include <vector>

#include <unistd.h>

#include "renderer.h"
#include "sample_player.h"

namespace {

int g_failures = 0;

void check(bool condition, const std::string &what) {
    if (condition) {
        std::printf("PASS %s\n", what.c_str());
    } else {
        std::printf("FAIL %s\n", what.c_str());
        ++g_failures;
    }
}

std::vector<uint8_t> read_file(const std::string &path) {
    std::vector<uint8_t> bytes;
    std::FILE *file = std::fopen(path.c_str(), "rb");
    if (file == nullptr) {
        return bytes;
    }
    std::fseek(file, 0, SEEK_END);
    const long size = std::ftell(file);
    std::fseek(file, 0, SEEK_SET);
    if (size > 0) {
        bytes.resize(static_cast<size_t>(size));
        if (std::fread(bytes.data(), 1, bytes.size(), file) != bytes.size()) {
            bytes.clear();
        }
    }
    std::fclose(file);
    return bytes;
}

bool write_file(const std::string &path, const std::vector<uint8_t> &bytes) {
    std::FILE *file = std::fopen(path.c_str(), "wb");
    if (file == nullptr) {
        return false;
    }
    const bool ok = std::fwrite(bytes.data(), 1, bytes.size(), file) == bytes.size();
    std::fclose(file);
    return ok;
}

void put_u16(std::vector<uint8_t> &bytes, size_t offset, uint16_t value) {
    bytes[offset] = static_cast<uint8_t>(value);
    bytes[offset + 1] = static_cast<uint8_t>(value >> 8);
}

void put_u32(std::vector<uint8_t> &bytes, size_t offset, uint32_t value) {
    for (int i = 0; i < 4; ++i) {
        bytes[offset + i] = static_cast<uint8_t>(value >> (8 * i));
    }
}

std::string temp_path(const std::string &directory, const std::string &name) {
    return (std::filesystem::path(directory) / name).string();
}

// One constant-PCM one-shot per key, matching the EARP1 layout. All zeros except the PCM plateau
// make the rendered signal equal to the velocity/release envelope itself.
std::vector<uint8_t> build_constant_pack(int16_t pcm_value, int frames) {
    constexpr size_t kHeaderBytes = ear_sample::kHeaderBytes;
    constexpr size_t kEntryBytes = ear_sample::kEntryBytes;
    constexpr size_t kCount = ear_sample::kEntryCount;
    const uint32_t data_offset = static_cast<uint32_t>(kHeaderBytes + kEntryBytes * kCount);
    const uint32_t payload_bytes = static_cast<uint32_t>(frames) * 2 * static_cast<uint32_t>(kCount);
    std::vector<uint8_t> pack(kHeaderBytes + kEntryBytes * kCount + payload_bytes, 0);
    std::memcpy(pack.data(), "EARP1\0\0\0", 8);
    put_u32(pack, 8, ear_sample::kFormatVersion);
    put_u32(pack, 12, ear_sample::kPackSampleRate);
    put_u32(pack, 16, ear_sample::kPackChannels);
    put_u32(pack, 20, static_cast<uint32_t>(kCount));
    put_u32(pack, 24, static_cast<uint32_t>(kHeaderBytes));
    put_u32(pack, 28, data_offset);
    put_u32(pack, 32, payload_bytes);
    put_u32(pack, 36, 0);

    std::vector<int16_t> payload(static_cast<size_t>(frames) * kCount, pcm_value);
    const uint8_t *payload_bytes_ptr = reinterpret_cast<const uint8_t *>(payload.data());
    uint8_t digest[32];
    ear_sample::sha256(payload_bytes_ptr, payload.size() * sizeof(int16_t), digest);
    std::memcpy(pack.data() + 40, digest, 32);

    for (size_t i = 0; i < kCount; ++i) {
        const size_t entry = kHeaderBytes + i * kEntryBytes;
        put_u16(pack, entry, static_cast<uint16_t>(ear_sample::kMidiLow + i));
        put_u16(pack, entry + 2, 0);
        put_u32(pack, entry + 4, static_cast<uint32_t>(frames));
        put_u32(pack, entry + 8, data_offset + static_cast<uint32_t>(i * frames * 2));
        std::memset(pack.data() + entry + 12, 0x5a, 32);
        ear_sample::sha256(payload_bytes_ptr + i * frames * 2,
                           static_cast<size_t>(frames) * 2, digest);
        std::memcpy(pack.data() + entry + 44, digest, 32);
    }
    std::memcpy(pack.data() + data_offset, payload_bytes_ptr, payload.size() * sizeof(int16_t));
    return pack;
}

// Renders a fixed number of frames in 64-frame blocks (the app's block granularity).
std::vector<float> render_blocks(ear_renderer *renderer, int channels, int total_frames) {
    constexpr int kBlock = 64;
    std::vector<float> out;
    out.reserve(static_cast<size_t>(total_frames) * channels);
    std::vector<float> block(static_cast<size_t>(kBlock) * channels);
    int remaining = total_frames;
    while (remaining > 0) {
        const int frames = std::min(kBlock, remaining);
        ear_renderer_render(renderer, block.data(), frames);
        out.insert(out.end(), block.begin(), block.begin() + static_cast<size_t>(frames) * channels);
        remaining -= frames;
    }
    return out;
}

float peak_of(const std::vector<float> &samples) {
    float peak = 0.0f;
    for (float value : samples) {
        peak = std::max(peak, std::fabs(value));
    }
    return peak;
}

bool all_exactly_zero(const std::vector<float> &samples) {
    for (float value : samples) {
        if (value != 0.0f) {
            return false;
        }
    }
    return true;
}

bool nearly(float actual, float expected, float tolerance) {
    return std::fabs(actual - expected) <= tolerance;
}

void test_sha256() {
    uint8_t digest[32];
    ear_sample::sha256(reinterpret_cast<const uint8_t *>("abc"), 3, digest);
    check(std::memcmp(digest,
                      "\xba\x78\x16\xbf\x8f\x01\xcf\xea\x41\x41\x40\xde\x5d\xae\x22\x23"
                      "\xb0\x03\x61\xa3\x96\x17\x7a\x9c\xb4\x10\xff\x61\xf2\x00\x15\xad",
                      32) == 0,
          "sha256($abc) matches the FIPS 180-2 vector");
    ear_sample::sha256(nullptr, 0, digest);
    check(std::memcmp(digest,
                      "\xe3\xb0\xc4\x42\x98\xfc\x1c\x14\x9a\xfb\xf4\xc8\x99\x6f\xb9\x24"
                      "\x27\xae\x41\xe4\x64\x9b\x93\x4c\xa4\x95\x99\x1b\x78\x52\xb8\x55",
                      32) == 0,
          "sha256(\"\") matches the empty-string vector");
}

struct RendererHandle {
    ear_renderer *value = nullptr;
    RendererHandle(int sample_rate, int channels) {
        if (ear_renderer_create(sample_rate, channels, &value) != EAR_OK) {
            value = nullptr;
        }
    }
    ~RendererHandle() { ear_renderer_destroy(value); }
    RendererHandle(const RendererHandle &) = delete;
    RendererHandle &operator=(const RendererHandle &) = delete;
};

void test_create_contract() {
    ear_renderer *renderer = nullptr;
    check(ear_renderer_create(22050, 1, &renderer) == EAR_ERR_SETTINGS && renderer == nullptr,
          "create rejects an unsupported sample rate");
    check(ear_renderer_create(48000, 3, &renderer) == EAR_ERR_SETTINGS && renderer == nullptr,
          "create rejects a channel count other than mono/stereo");
    check(ear_renderer_create(48000, 1, nullptr) == EAR_ERR_INVALID_ARGUMENT,
          "create rejects a null out-pointer");
    RendererHandle handle(48000, 1);
    check(handle.value != nullptr, "create accepts 48 kHz mono");
    if (handle.value == nullptr) {
        return;
    }
    int sample_rate = 0;
    int channels = 0;
    check(ear_renderer_format(handle.value, &sample_rate, &channels) == EAR_OK &&
              sample_rate == 48000 && channels == 1,
          "format reports the negotiated 48 kHz mono");
    float block[64] = {};
    check(ear_renderer_note_on(handle.value, 60, 0) == EAR_ERR_VELOCITY,
          "note_on rejects velocity 0");
    check(ear_renderer_note_on(handle.value, 60, 128) == EAR_ERR_VELOCITY,
          "note_on rejects velocity above 127");
    check(ear_renderer_note_on(handle.value, 128, 96) == EAR_ERR_NOTE,
          "note_on rejects MIDI note 128");
    check(ear_renderer_note_off(handle.value, -1) == EAR_ERR_NOTE,
          "note_off rejects a negative MIDI note");
    check(ear_renderer_set_gain(handle.value, -1.0f) == EAR_ERR_GAIN,
          "set_gain rejects a negative gain");
    check(ear_renderer_set_gain(handle.value, 10.5f) == EAR_ERR_GAIN,
          "set_gain rejects gain above 10");
    check(ear_renderer_set_polyphony(handle.value, 0) == EAR_ERR_POLYPHONY,
          "set_polyphony rejects 0");
    check(ear_renderer_set_polyphony(handle.value, 257) == EAR_ERR_POLYPHONY,
          "set_polyphony rejects 257");
    check(ear_renderer_load_soundfont(handle.value, nullptr, 0, 0) == EAR_ERR_INVALID_ARGUMENT,
          "load_soundfont rejects a null path");
    check(ear_renderer_render(handle.value, nullptr, 64) == EAR_ERR_BUFFER,
          "render rejects a null buffer");
    check(ear_renderer_render(handle.value, block, 0) == EAR_ERR_INVALID_ARGUMENT,
          "render rejects zero frames");
}

void test_idle_silence() {
    RendererHandle handle(48000, 1);
    if (handle.value == nullptr) {
        check(false, "idle silence: renderer create");
        return;
    }
    check(all_exactly_zero(render_blocks(handle.value, 1, 4096)),
          "a renderer with no pack renders exact zero");
}

void test_real_pack_load(const std::string &pack_path) {
    ear_sample::SamplePack pack;
    const ear_sample::PackStatus status = pack.load(pack_path.c_str());
    check(status == ear_sample::PackStatus::kOk, "the generated pack loads and validates");
    check(pack.samples().size() == ear_sample::kEntryCount,
          "the pack exposes 88 samples");
    check(pack.samples().front().midi == 21 && pack.samples().back().midi == 108,
          "the pack covers MIDI 21-108");
    check(pack.samples().front().frames == 120000,
          "each entry keeps its 120000 frames");
    check(pack.resident_bytes() == 88u * 120000u * 2u,
          "the pack holds one resident 21.12 MB PCM allocation");
    check(pack.find(20) == nullptr && pack.find(109) == nullptr,
          "find rejects keys outside the pack range");

    RendererHandle renderer(48000, 1);
    if (renderer.value == nullptr) {
        check(false, "real pack: renderer create");
        return;
    }
    check(ear_renderer_load_soundfont(renderer.value, pack_path.c_str(), 0, 0) == EAR_OK,
          "the sample renderer loads the pack through the shared load_soundfont call");
    ear_renderer_set_gain(renderer.value, 1.0f);
    ear_renderer_set_polyphony(renderer.value, 32);
    check(ear_renderer_note_on(renderer.value, 10, 100) == EAR_OK,
          "a valid MIDI note outside 21-108 is accepted without a voice");
    check(all_exactly_zero(render_blocks(renderer.value, 1, 64)),
          "an out-of-range note stays silent");

    // Level is checked against the pack's own PCM, not a bank-specific constant, so a
    // recalibrated bank (for example the V4 dark calibration) cannot silently break the test.
    const ear_sample::Sample *anchor = pack.find(21);
    if (anchor == nullptr) {
        check(false, "real pack: MIDI 21 anchor missing");
        return;
    }
    constexpr float kEngineLevel = 0.5238f;  // measured reference-renderer scale (t12 report)
    float rawPeak = 0.0f;
    for (size_t i = 0; i < anchor->frames; ++i) {
        rawPeak = std::max(rawPeak, std::fabs(static_cast<float>(anchor->pcm[i])));
    }
    rawPeak /= 32768.0f;
    ear_renderer_note_on(renderer.value, 21, 127);
    std::vector<float> note = render_blocks(renderer.value, 1, 48000);
    const float peak = peak_of(note);
    const float expectedPeak = rawPeak * kEngineLevel;
    check(std::fabs(peak - expectedPeak) <= expectedPeak * 0.005f,
          "velocity 127 peak matches the pack PCM times the measured engine level");
    double rawSum = 0.0;
    double sum = 0.0;
    for (int i = 12000; i < 31200; ++i) {
        const float raw = static_cast<float>(anchor->pcm[i]) / 32768.0f;
        rawSum += static_cast<double>(raw) * raw;
        sum += static_cast<double>(note[i]) * note[i];
    }
    const double rawRms = std::sqrt(rawSum / 19200.0) * kEngineLevel;
    const double rms = std::sqrt(sum / 19200.0);
    check(std::fabs(20.0 * std::log10(rms) - 20.0 * std::log10(rawRms)) < 0.06,
          "velocity 127 sustain RMS matches the pack PCM times the measured engine level");
}

void test_corrupt_pack_rejection(const std::string &pack_path, const std::string &directory) {
    const std::vector<uint8_t> good = read_file(pack_path);
    check(good.size() > 100, "corruption tests can read the generated pack");
    if (good.size() <= 100) {
        return;
    }
    constexpr size_t kEntryBytes = ear_sample::kEntryBytes;
    const size_t data_offset = ear_sample::kHeaderBytes + kEntryBytes * ear_sample::kEntryCount;

    struct Case {
        const char *name;
        const char *file;
        size_t offset;  // ignored when bytes is empty
        std::vector<uint8_t> bytes;
        bool flip;      // XOR the existing bytes instead of overwriting them
        ear_error expected;
    };
    std::vector<Case> cases;
    cases.push_back({"wrong magic", "bad_magic.bin", 0, {0xff}, true, EAR_ERR_SOUNDFONT_FORMAT});
    cases.push_back({"wrong version", "bad_version.bin", 8, {2}, false, EAR_ERR_SOUNDFONT_FORMAT});
    cases.push_back({"wrong entry count", "bad_count.bin", 20, {0x57}, false,
                     EAR_ERR_SOUNDFONT_FORMAT});
    // A PCM change keeps the header valid but breaks both the payload hash and the entry hash.
    cases.push_back({"corrupt PCM (payload hash)", "bad_payload.bin", data_offset + 100,
                     {0xff}, true, EAR_ERR_SOUNDFONT_FORMAT});
    // Changing only the stored per-entry hash leaves the payload hash intact.
    cases.push_back({"corrupt entry hash", "bad_entry_hash.bin",
                     ear_sample::kHeaderBytes + 44, {0xff}, true, EAR_ERR_SOUNDFONT_FORMAT});
    cases.push_back({"missing key (MIDI 20)", "missing_key.bin",
                     ear_sample::kHeaderBytes + 0, {20, 0}, false, EAR_ERR_SOUNDFONT_FORMAT});
    cases.push_back({"duplicate key (MIDI 21 twice)", "duplicate_key.bin",
                     ear_sample::kHeaderBytes + kEntryBytes, {21, 0}, false,
                     EAR_ERR_SOUNDFONT_FORMAT});
    cases.push_back({"truncated file", "truncated.bin", 0, {}, false, EAR_ERR_SOUNDFONT_FORMAT});

    for (const Case &test : cases) {
        std::vector<uint8_t> bytes = good;
        std::string path = temp_path(directory, test.file);
        if (test.bytes.empty()) {
            bytes.resize(100);
        } else if (test.flip) {
            for (size_t i = 0; i < test.bytes.size(); ++i) {
                bytes[test.offset + i] ^= test.bytes[i];
            }
        } else {
            std::memcpy(bytes.data() + test.offset, test.bytes.data(), test.bytes.size());
        }
        if (!write_file(path, bytes)) {
            check(false, std::string(test.name) + ": cannot write the corrupt copy");
            continue;
        }
        RendererHandle renderer(48000, 1);
        const ear_error error = ear_renderer_load_soundfont(renderer.value, path.c_str(), 0, 0);
        check(error == test.expected,
              std::string(test.name) + " is refused with the shared SoundFont error");
        std::remove(path.c_str());
    }

    RendererHandle renderer(48000, 1);
    check(ear_renderer_load_soundfont(renderer.value, temp_path(directory, "missing.bin").c_str(),
                                      0, 0) == EAR_ERR_SOUNDFONT_OPEN,
          "a missing file is reported as an open failure");
    check(ear_renderer_load_soundfont(renderer.value, pack_path.c_str(), 0, 128) ==
              EAR_ERR_PROGRAM_SELECT,
          "load_soundfont validates the program number");
}

void test_velocity_mapping(const std::string &pack_path, const std::string &directory) {
    const std::string synthetic = temp_path(directory, "constant_velocity.bin");
    if (!write_file(synthetic, build_constant_pack(16384, 48000))) {
        check(false, "velocity mapping: cannot write the synthetic pack");
        return;
    }
    RendererHandle renderer(48000, 1);
    check(ear_renderer_load_soundfont(renderer.value, synthetic.c_str(), 0, 0) == EAR_OK,
          "the synthetic constant pack loads");
    ear_renderer_set_gain(renderer.value, 1.0f);
    const float plateau = 0.5f * 0.5238f;
    for (int velocity : {1, 32, 64, 96, 127}) {
        ear_renderer_system_reset(renderer.value);
        check(ear_renderer_note_on(renderer.value, 60, velocity) == EAR_OK,
              "synthetic note_on succeeds");
        const std::vector<float> block = render_blocks(renderer.value, 1, 64);
        const float ratio = static_cast<float>(velocity) / 127.0f;
        check(nearly(block[0], plateau * ratio * ratio, 1.5e-5f),
              "velocity " + std::to_string(velocity) + " follows (v/127)^2");
    }
    (void)pack_path;
    std::remove(synthetic.c_str());
}

void test_release_ramp(const std::string &directory) {
    const std::string synthetic = temp_path(directory, "constant_release.bin");
    if (!write_file(synthetic, build_constant_pack(16384, 48000))) {
        check(false, "release ramp: cannot write the synthetic pack");
        return;
    }
    const double decay48 = std::exp(-1.0 / (0.001491 * 48000.0));
    const float plateau = 0.5f * 0.5238f;

    RendererHandle renderer(48000, 1);
    if (ear_renderer_load_soundfont(renderer.value, synthetic.c_str(), 0, 0) != EAR_OK) {
        check(false, "release ramp: cannot load the synthetic pack");
        return;
    }
    ear_renderer_set_gain(renderer.value, 1.0f);
    ear_renderer_note_on(renderer.value, 60, 127);
    const std::vector<float> before = render_blocks(renderer.value, 1, 4800);
    check(nearly(before.back(), plateau, 1e-6f),
          "the note holds the velocity level until note-off");
    ear_renderer_note_off(renderer.value, 60);
    const std::vector<float> after = render_blocks(renderer.value, 1, 832);

    check(nearly(after[0], plateau, 1e-6f),
          "the first released frame starts at the note-off level (no click)");
    bool monotonic = true;
    for (size_t i = 1; i < 704; ++i) {
        if (after[i] > after[i - 1] + 1e-9f) {
            monotonic = false;
            break;
        }
    }
    check(monotonic, "the release envelope decreases every frame");
    check(nearly(after[1], plateau * static_cast<float>(decay48), 2e-6f),
          "the second released frame uses the 1.491 ms exponential decay");
    check(nearly(after[64], plateau * static_cast<float>(std::pow(decay48, 64)), 2e-6f),
          "the release is time based, not block based, at frame 64");
    check(nearly(after[703], plateau * static_cast<float>(std::pow(decay48, 703)), 2e-6f),
          "the release still follows the exponential just before it is cut");
    check(after[703] > 0.0f, "the release has not reached zero before 704 frames");
    check(all_exactly_zero(std::vector<float>(after.begin() + 704, after.end())),
          "exact silence begins 704 frames (14.67 ms) after note-off at 48 kHz");

    // 44.1 kHz uses the measured 640-frame tail.
    RendererHandle renderer44(44100, 1);
    if (ear_renderer_load_soundfont(renderer44.value, synthetic.c_str(), 0, 0) != EAR_OK) {
        check(false, "release ramp: cannot load the synthetic pack at 44.1 kHz");
        return;
    }
    ear_renderer_set_gain(renderer44.value, 1.0f);
    ear_renderer_note_on(renderer44.value, 60, 127);
    render_blocks(renderer44.value, 1, 4410);
    ear_renderer_note_off(renderer44.value, 60);
    const std::vector<float> after44 = render_blocks(renderer44.value, 1, 704);
    check(after44[639] > 0.0f && all_exactly_zero(std::vector<float>(after44.begin() + 640,
                                                                    after44.end())),
          "exact silence begins 640 frames (14.51 ms) after note-off at 44.1 kHz");

    // all_notes_off and system_reset kill voices immediately.
    ear_renderer_note_on(renderer.value, 60, 127);
    render_blocks(renderer.value, 1, 128);
    ear_renderer_all_notes_off(renderer.value);
    check(all_exactly_zero(render_blocks(renderer.value, 1, 256)),
          "all_notes_off silences every voice immediately");
    ear_renderer_note_on(renderer.value, 60, 127);
    render_blocks(renderer.value, 1, 128);
    ear_renderer_system_reset(renderer.value);
    check(all_exactly_zero(render_blocks(renderer.value, 1, 256)),
          "system_reset silences every voice immediately");
    std::remove(synthetic.c_str());
}

void test_polyphony(const std::string &directory) {
    const std::string synthetic = temp_path(directory, "constant_polyphony.bin");
    if (!write_file(synthetic, build_constant_pack(16384, 48000))) {
        check(false, "polyphony: cannot write the synthetic pack");
        return;
    }
    const float plateau = 0.5f * 0.5238f;
    RendererHandle renderer(48000, 1);
    if (ear_renderer_load_soundfont(renderer.value, synthetic.c_str(), 0, 0) != EAR_OK) {
        check(false, "polyphony: cannot load the synthetic pack");
        return;
    }
    ear_renderer_set_gain(renderer.value, 1.0f);
    check(ear_renderer_set_polyphony(renderer.value, 2) == EAR_OK, "polyphony 2 is accepted");
    ear_renderer_note_on(renderer.value, 60, 127);
    ear_renderer_note_on(renderer.value, 64, 127);
    ear_renderer_note_on(renderer.value, 67, 127);
    check(nearly(render_blocks(renderer.value, 1, 32)[0], 2.0f * plateau, 1e-5f),
          "three note-ons at polyphony 2 keep exactly the two newest voices");
    check(ear_renderer_set_polyphony(renderer.value, 1) == EAR_OK,
          "lowering polyphony to 1 is accepted");
    check(nearly(render_blocks(renderer.value, 1, 32)[0], plateau, 1e-5f),
          "lowering polyphony trims the oldest voice");

    // The contract's default pool is 32 voices.
    RendererHandle defaults(48000, 1);
    if (ear_renderer_load_soundfont(defaults.value, synthetic.c_str(), 0, 0) != EAR_OK) {
        check(false, "polyphony: cannot load the synthetic pack for the default check");
        std::remove(synthetic.c_str());
        return;
    }
    ear_renderer_set_gain(defaults.value, 1.0f);
    for (int i = 0; i < 40; ++i) {
        ear_renderer_note_on(defaults.value, 60, 127);
    }
    check(nearly(render_blocks(defaults.value, 1, 32)[0], 32.0f * plateau, 1e-4f),
          "the default voice pool caps 40 note-ons at 32 voices");
    std::remove(synthetic.c_str());
}

void test_channels(const std::string &pack_path) {
    ear_sample::SamplePack pack;
    if (pack.load(pack_path.c_str()) != ear_sample::PackStatus::kOk) {
        check(false, "channels: cannot load the pack for the level anchor");
        return;
    }
    const ear_sample::Sample *anchor = pack.find(60);
    if (anchor == nullptr) {
        check(false, "channels: MIDI 60 anchor missing");
        return;
    }
    float rawPeak = 0.0f;
    for (size_t i = 0; i < anchor->frames; ++i) {
        rawPeak = std::max(rawPeak, std::fabs(static_cast<float>(anchor->pcm[i])));
    }
    const float expectedPeak = rawPeak / 32768.0f * 0.5238f;
    for (int sample_rate : {48000, 44100}) {
        RendererHandle mono(sample_rate, 1);
        RendererHandle stereo(sample_rate, 2);
        if (ear_renderer_load_soundfont(mono.value, pack_path.c_str(), 0, 0) != EAR_OK ||
            ear_renderer_load_soundfont(stereo.value, pack_path.c_str(), 0, 0) != EAR_OK) {
            check(false, "channels: cannot load the pack");
            return;
        }
        ear_renderer_set_gain(mono.value, 1.0f);
        ear_renderer_set_gain(stereo.value, 1.0f);
        ear_renderer_note_on(mono.value, 60, 127);
        ear_renderer_note_on(stereo.value, 60, 127);
        const std::vector<float> mono_out = render_blocks(mono.value, 1, 4096);
        const std::vector<float> stereo_out = render_blocks(stereo.value, 2, 4096);
        bool equal = true;
        for (int frame = 0; frame < 4096 && equal; ++frame) {
            if (stereo_out[2 * frame] != stereo_out[2 * frame + 1] ||
                stereo_out[2 * frame] != mono_out[frame]) {
                equal = false;
            }
        }
        check(equal, std::to_string(sample_rate) +
                         " Hz: mono output equals both identical stereo channels");
        const float stereo_peak = peak_of(stereo_out);
        check(std::fabs(stereo_peak - expectedPeak) <= expectedPeak * 0.01f,
              std::to_string(sample_rate) + " Hz: stereo renders the pack level");
    }
}

}  // namespace

int main(int argc, char **argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s <earby-string-pack.bin>\n", argv[0]);
        return 2;
    }
    const std::string pack_path = argv[1];
    if (read_file(pack_path).empty()) {
        std::fprintf(stderr, "cannot read pack: %s\n", pack_path.c_str());
        return 2;
    }

    std::filesystem::path directory =
        std::filesystem::temp_directory_path() /
        ("ear_sample_player_test_" + std::to_string(static_cast<long>(::getpid())));
    std::error_code error;
    std::filesystem::create_directories(directory, error);
    const std::string temp_dir = directory.string();

    test_sha256();
    test_create_contract();
    test_idle_silence();
    test_real_pack_load(pack_path);
    test_corrupt_pack_rejection(pack_path, temp_dir);
    test_velocity_mapping(pack_path, temp_dir);
    test_release_ramp(temp_dir);
    test_polyphony(temp_dir);
    test_channels(pack_path);

    std::filesystem::remove_all(directory, error);
    if (g_failures == 0) {
        std::printf("all sample player checks passed\n");
        return 0;
    }
    std::fprintf(stderr, "%d sample player check(s) failed\n", g_failures);
    return 1;
}
